contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0, "balance check");
        uint before = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterDeposit = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(afterDeposit == before);
    }
}

