// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 before;
        try c.depositsCount() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.withdraw(value) { reverted = false; } catch { reverted = true; }
        uint256 afterDeposit;
        try c.depositsCount() returns (uint256 __r) { afterDeposit = __r; } catch { return; }
        assertTrue(afterDeposit == before);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
